+/// One indexed fact: the row's storage scope and its text.
+#[derive(Clone)]
+struct Row {
+    id: &'static str,
+    scope: ScopeKey,
+    text: &'static str,
+}
+
+fn scope(ws: &str, sess: Option<&str>, task: Option<&str>) -> ScopeKey {
+    ScopeKey {
+        workspace_id: ws.to_string(),
+        session_id: sess.map(str::to_string),
+        task_id: task.map(str::to_string),
+    }
+}
