+/// Index `rows` into `store`, one call per row, under each row's own scope.
+async fn index_all(store: &TursoLexical, rows: &[Row]) {
+    for row in rows {
+        store
+            .index(&row.scope, &FactId(row.id.to_string()), row.text)
+            .await
+            .expect("index");
+    }
+}
